module find_squares_3x3(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [2:0] grid_row0,\n    input wire [2:0] grid_row1,\n    input wire [2:0] grid_row2,\n    output reg [1:0] square1_row,\n    output reg [1:0] square1_col,\n    output reg [1:0] square1_size,\n    output reg [1:0] square2_row,\n    output reg [1:0] square2_col,\n    output reg [1:0] square2_size,\n    output reg done\n);\n\n    // State declarations\n    localparam [1:0] IDLE       = 2'd0;\n    localparam [1:0] PRECOMPUTE = 2'd1;\n    localparam [1:0] SEARCH     = 2'd2;\n    localparam [1:0] DONE_STATE = 2'd3;\n\n    reg [1:0] state;\n    reg [8:0] x_mask_reg;\n    reg [13:0] valid_reg;\n    reg [3:0] i_reg;\n    reg [3:0] j_reg;\n    wire [8:0] combined_mask;\n    reg [14:0] valid_compute;\n\n    // Square property functions\n    function [8:0] get_mask;\n        input [3:0] idx;\n        begin\n            case (idx)\n                4'd0:  get_mask = 9'b000000001;\n                4'd1:  get_mask = 9'b000011011;\n                4'd2:  get_mask = 9'b111111111;\n                4'd3:  get_mask = 9'b000000010;\n                4'd4:  get_mask = 9'b000110110;\n                4'd5:  get_mask = 9'b000000100;\n                4'd6:  get_mask = 9'b000001000;\n                4'd7:  get_mask = 9'b011011000;\n                4'd8:  get_mask = 9'b000010000;\n                4'd9:  get_mask = 9'b110110000;\n                4'd10: get_mask = 9'b000100000;\n                4'd11: get_mask = 9'b001000000;\n                4'd12: get_mask = 9'b010000000;\n                4'd13: get_mask = 9'b100000000;\n                default: get_mask = 9'd0;\n            endcase\n        end\n    endfunction\n\n    function [1:0] get_row;\n        input [3:0] idx;\n        begin\n            case (idx)\n                4'd0, 4'd1, 4'd2, 4'd3, 4'd4, 4'd5: get_row = 2'd0;\n                4'd6, 4'd7, 4'd8, 4'd9, 4'd10:      get_row = 2'd1;\n                default:                            get_row = 2'd2;\n            endcase\n        end\n    endfunction\n\n    function [1:0] get_col;\n        input [3:0] idx;\n        begin\n            case (idx)\n                4'd0,4'd1,4'd2,4'd6,4'd7,4'd11:    get_col = 2'd0;\n                4'd3,4'd4,4'd8,4'd9,4'd12:       get_col = 2'd1;\n                default:                            get_col = 2'd2;\n            endcase\n        end\n    endfunction\n\n    function [1:0] get_size;\n        input [3:0] idx;\n        begin\n            case (idx)\n                4'd1,4'd4,4'd7,4'd9: get_size = 2'd2;\n                4'd2:                get_size = 2'd3;\n                default:             get_size = 2'd1;\n            endcase\n        end\n    endfunction\n\n    // Combined mask calculation\n    assign combined_mask = get_mask(i_reg) | get_mask(j_reg);\n\n    // Main state machine\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            i_reg <= 4'd0;\n            j_reg <= 4'd0;\n            x_mask_reg <= 9'd0;\n            valid_reg <= 14'd0;\n            square1_row <= 2'd0;\n            square1_col <= 2'd0;\n            square1_size <= 2'd0;\n            square2_row <= 2'd0;\n            square2_col <= 2'd0;\n            square2_size <= 2'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        state <= PRECOMPUTE;\n                    end\n                end\n\n                PRECOMPUTE: begin\n                    x_mask_reg <= {grid_row2, grid_row1, grid_row0};\n                    valid_compute <= 14'd0;\n                    for (integer k=0; k <14; k=k+1) begin\n                        if ((get_mask(k) & {grid_row2, grid_row1, grid_row0}) == get_mask(k)) \n                            valid_compute[k] <= 1'b1;\n                        else\n                            valid_compute[k] <= 1'b0;\n                    end\n                    valid_reg <= valid_compute;\n                    i_reg <= 4'd0;\n                    j_reg <= 4'd1;\n                    state <= SEARCH;\n                end\n\n                SEARCH: begin\n                    if (i_reg < 4'd13) begin\n                        if (valid_reg[i_reg] && valid_reg[j_reg] && (combined_mask == x_mask_reg)) begin\n                            square1_row <= get_row(i_reg);\n                            square1_col <= get_col(i_reg);\n                            square1_size <= get_size(i_reg);\n                            square2_row <= get_row(j_reg);\n                            square2_col <= get_col(j_reg);\n                            square2_size <= get_size(j_reg);\n                            state <= DONE_STATE;\n                        end else if (j_reg == 4'd13) begin\n                            i_reg <= i_reg + 4'd1;\n                            j_reg <= i_reg + 4'd2;\n                        end else begin\n                            j_reg <= j_reg + 4'd1;\n                        end\n                    end else begin\n                        square1_row <= 2'd0;\n                        square1_col <= 2'd0;\n                        square1_size <= 2'd0;\n                        square2_row <= 2'd0;\n                        square2_col <= 2'd0;\n                        square2_size <= 2'd0;\n                        state <= DONE_STATE;\n                    end\n                end\n\n                DONE_STATE: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule